CREATE DATABASE IF NOT EXISTS drop_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE drop_demo;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, balance DECIMAL(12,2) NOT NULL DEFAULT 1000.00, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE game_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, game VARCHAR(20) NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, multiplier DECIMAL(8,2) DEFAULT NULL, result VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), CONSTRAINT fk_history_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);